using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace InertiaCore.TypeGen;

/// <summary>
/// Generates a <c>routes.ts</c> module from collected route metadata. The generated module
/// exposes a strongly typed <c>route(name, params)</c> helper (a Ziggy-style API) where the
/// route name and its parameter names/types are checked by TypeScript.
/// </summary>
public sealed class InertiaRouteScriptGenerator
{
    private const string Header =
        "// <auto-generated />\n" +
        "// Generated by InertiaCore.TypeGen. Do not edit this file manually.\n" +
        "// Re-run the generator to refresh it.\n";

    /// <summary>
    /// Generates the <c>routes.ts</c> content for the given routes.
    /// </summary>
    /// <param name="routes">The named routes to emit.</param>
    /// <returns>The generated TypeScript module content.</returns>
    public string Generate(IReadOnlyList<InertiaRouteDto> routes)
    {
        ArgumentNullException.ThrowIfNull(routes);

        IReadOnlyList<InertiaRouteDto> ordered = routes
            .OrderBy(static r => r.Name, StringComparer.Ordinal)
            .ToList();

        var builder = new StringBuilder();
        builder.Append(Header);
        builder.Append('\n');

        // export type InertiaRouteName = 'a' | 'b' | ...;
        builder.Append("export type InertiaRouteName = ")
            .Append(string.Join(" | ", ordered.Select(static r => Quote(r.Name))))
            .Append(";\n");

        // export interface InertiaRouteParams { ... }
        builder.Append('\n');
        builder.Append("export interface InertiaRouteParams {\n");
        foreach (InertiaRouteDto route in ordered)
        {
            builder.Append("  ").Append(Quote(route.Name)).Append(": ")
                .Append(RenderParamsType(route)).Append(";\n");
        }

        builder.Append("}\n");

        // const inertiaRouteDefs = { ... };
        builder.Append('\n');
        builder.Append("const inertiaRouteDefs = {\n");
        foreach (InertiaRouteDto route in ordered)
        {
            string methods = string.Join(", ", route.HttpMethods.Select(Quote));
            builder.Append("  ").Append(Quote(route.Name)).Append(": { pattern: ")
                .Append(Quote(route.Pattern)).Append(", methods: [").Append(methods).Append("] },\n");
        }

        builder.Append("};\n");

        // export type InertiaRouteArgs<K> = ...;
        builder.Append('\n');
        builder.Append(
            "export type InertiaRouteArgs<K extends InertiaRouteName> =\n" +
            "  keyof InertiaRouteParams[K] extends never\n" +
            "    ? [params?: Record<string, string | number | (string | number)[] | undefined>]\n" +
            "    : [params: InertiaRouteParams[K] & Record<string, string | number | (string | number)[] | undefined>];\n");

        // export function route<K>(name, ...args) { ... }
        builder.Append('\n');
        builder.Append(RouteFunctionSource());

        return builder.ToString();
    }

    private static string RenderParamsType(InertiaRouteDto route)
    {
        if (route.Parameters.Count == 0)
        {
            return "{}";
        }

        string members = string.Join(" ", route.Parameters.Select(static p =>
        {
            string optional = p.IsOptional ? "?" : string.Empty;
            return p.Name + optional + ": " + MapParameterType(p) + ";";
        }));

        return "{ " + members + " }";
    }

    /// <summary>
    /// Maps a route parameter constraint to a TypeScript type. Numeric constraints accept a
    /// number (or a string); identifier-like constraints such as <c>guid</c> stay strings.
    /// </summary>
    private static string MapParameterType(InertiaRouteParameterDto parameter)
    {
        if (parameter.IsCatchAll)
        {
            return "string | number | (string | number)[]";
        }

        string? constraint = parameter.Constraint?.ToLowerInvariant();

        if (constraint is null)
        {
            return "string | number";
        }

        if (constraint is "int" or "uint" or "long" or "ulong" or "short" or "ushort"
            or "byte" or "sbyte" or "decimal" or "double" or "float" or "single"
            or "i8" or "i16" or "i32" or "i64" or "u8" or "u16" or "u32" or "u64")
        {
            return "string | number";
        }

        if (constraint is "guid" or "datetime" or "datetimeoffset" or "date" or "time")
        {
            return "string";
        }

        if (constraint is "bool" or "boolean")
        {
            return "boolean | string";
        }

        return "string | number";
    }

    private static string Quote(string value) =>
        "'" + value.Replace("\\", "\\\\", StringComparison.Ordinal)
                   .Replace("'", "\\'", StringComparison.Ordinal) + "'";

    private static string RouteFunctionSource() =>
        """
        export function route<K extends InertiaRouteName>(name: K, ...args: InertiaRouteArgs<K>): string {
          const def = inertiaRouteDefs[name];
          const supplied = (args.length > 0 && args[0] !== undefined ? args[0] : {}) as Record<string, unknown>;
          const pathKeys: string[] = [];
          const path = def.pattern.replace(/\{([^}]+)\}/g, (_match: string, token: string) => {
            const key = (token.startsWith('*') ? token.slice(1) : token).replace(/\?$/, '');
            pathKeys.push(key);
            const value = supplied[key];
            if (value === undefined || value === null) {
              return '';
            }
            return Array.isArray(value)
              ? value.map((item) => encodeURIComponent(String(item))).join('/')
              : encodeURIComponent(String(value));
          });
          const query: string[] = [];
          for (const key of Object.keys(supplied)) {
            if (pathKeys.indexOf(key) !== -1) continue;
            const value = supplied[key];
            if (value === undefined || value === null) continue;
            if (Array.isArray(value)) {
              for (const item of value) {
                query.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(item)));
              }
            } else {
              query.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
            }
          }
          return query.length > 0 ? path + '?' + query.join('&') : path;
        }
        """;
}
